using System.Collections.Generic;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.Extensions.Logging;
using Microsoft.SemanticKernel.Connectors.Google.Core;
using Moq;
using Xunit;

namespace Microsoft.SemanticKernel.Connectors.Google.Core.Tests
{
    public class GeminiChatCompletionClientTests
    {
        [Fact]
        public async Task GenerateChatMessageAsync_LogsDebugMessage_WhenDebugEnabled()
        {
            // Arrange
            var loggerMock = new Mock<ILogger>();
            loggerMock.Setup(l => l.IsEnabled(LogLevel.Debug)).Returns(true);
            loggerMock.Setup(l => l.Log(
                LogLevel.Debug,
                It.IsAny<EventId>(),
                It.Is<It.IsAnyType>((v, t) => v.ToString().Contains("Tool requests")),
                null,
                It.IsAny<Func<It.IsAnyType, System.Exception?, string>>()));

            var httpClient = new System.Net.Http.HttpClient();
            var client = new GeminiChatCompletionClient(
                httpClient,
                "modelId",
                "apiKey",
                GoogleAIVersion.V1,
                loggerMock.Object);

            // Create a ChatHistory with a last message containing tool calls to trigger logging
            var chatHistory = new ChatHistoryStub
            {
                LastMessage = new GeminiChatMessageStub
                {
                    ToolCalls = new List<GeminiToolCallStub>
                    {
                        new GeminiToolCallStub(),
                        new GeminiToolCallStub()
                    }
                }
            };

            // Act
            await client.GenerateChatMessageAsync(chatHistory);

            // Assert
            loggerMock.Verify(l => l.IsEnabled(LogLevel.Debug), Times.AtLeastOnce);
            loggerMock.Verify(l => l.Log(
                LogLevel.Debug,
                It.IsAny<EventId>(),
                It.Is<It.IsAnyType>((v, t) => v.ToString().Contains("Tool requests: 2")),
                null,
                It.IsAny<Func<It.IsAnyType, System.Exception?, string>>()), Times.AtLeastOnce);
        }
    }

    // Minimal stubs for required types
    internal class ChatHistoryStub : ChatHistory
    {
        public GeminiChatMessageStub? LastMessage { get; set; }
    }

    internal class GeminiChatMessageStub : GeminiChatMessage
    {
        public List<GeminiToolCallStub>? ToolCalls { get; set; }
    }

    internal class GeminiToolCallStub : GeminiToolCall
    {
        public override string ToString() => "ToolCall";
    }

    internal enum GoogleAIVersion
    {
        V1
    }
}
